# 바구니로 결제: 프로모션 코드 구현

## 1. `pricing.ts`

```ts
// pricing.ts
export type Category = 'grocery' | 'household' | 'alcohol';
export type DiscountableCategory = Exclude<Category, 'alcohol'>;

export interface LineItem {
  sku: string;
  name: string;
  unitPrice: number; // 원, 부가세 포함 판매가 (예: 1990)
  qty: number;
  category: Category;
}

export interface Cart {
  items: LineItem[];
  memberTier: 'none' | 'plus';
}

export type PromoRejectReason = 'unknown' | 'expired' | 'below_minimum' | 'no_eligible_items';

export interface PromoDefinition {
  readonly code: string; // 대문자로 저장
  readonly kind: 'percent' | 'fixed';
  /** percent: 정수 %, fixed: 원 */
  readonly value: number;
  /** 대상 카테고리 비주류 상품의 판매가(멤버십 할인 전) 합계 기준 */
  readonly minEligibleAmount: number;
  /** YYYY-MM-DD, Asia/Seoul, 해당일 포함 */
  readonly validThrough: string;
  readonly categories: readonly DiscountableCategory[];
}

export const PROMO_CODES: readonly PromoDefinition[] = [
  { code: 'FRESH10', kind: 'percent', value: 10, minEligibleAmount: 40_000, validThrough: '2025-12-31', categories: ['grocery', 'household'] },
  { code: 'SAVE5000', kind: 'fixed', value: 5_000, minEligibleAmount: 25_000, validThrough: '2025-06-30', categories: ['grocery', 'household'] },
  { code: 'HOME15', kind: 'percent', value: 15, minEligibleAmount: 0, validThrough: '2025-12-31', categories: ['household'] },
];

export const STORE_TIME_ZONE = 'Asia/Seoul';
export const MEMBER_DISCOUNT_PERCENT: Readonly<Record<Cart['memberTier'], number>> = { none: 0, plus: 5 };

/** 법무: 주류는 프로모션·멤버십 모두 할인 불가 */
const DISCOUNTABLE: Readonly<Record<Category, boolean>> = { grocery: true, household: true, alcohol: false };
/** 재무: grocery 면세, household·alcohol 과세 (포함가에서 10/110 분리) */
const TAXABLE: Readonly<Record<Category, boolean>> = { grocery: false, household: true, alcohol: true };

export interface PricedLine {
  sku: string;
  name: string;
  category: Category;
  unitPrice: number;
  qty: number;
  grossAmount: number;    // unitPrice × qty
  memberDiscount: number;
  promoDiscount: number;
  netAmount: number;      // 결제 금액(부가세 포함)
  taxable: boolean;
  vat: number;            // netAmount에 포함된 부가세
  supplyAmount: number;   // netAmount - vat
}

export type PromoOutcome =
  | { status: 'none' }
  | { status: 'applied'; code: string; discount: number }
  | { status: 'rejected'; code: string; reason: PromoRejectReason };

export interface PriceResult {
  lines: PricedLine[];
  subtotal: number;
  memberDiscount: number;
  promoDiscount: number;
  total: number;               // 결제 총액. 부가세를 별도로 더하지 않음
  vat: number;                 // total에 포함된 부가세 합
  taxableSupplyAmount: number; // 과세 공급가액
  exemptAmount: number;        // 면세 금액
  promo: PromoOutcome;
}

interface BaseLine {
  item: LineItem;
  grossAmount: number;
  memberDiscount: number;
  afterMember: number;
}

interface PromoEvaluation {
  outcome: PromoOutcome;
  perLine: number[];
}

/** 음이 아닌 정수 나눗셈의 half-up 반올림 (부동소수점 미사용) */
export function divRoundHalfUp(numerator: number, denominator: number): number {
  if (!Number.isSafeInteger(numerator) || numerator < 0 || !Number.isSafeInteger(denominator) || denominator <= 0) {
    throw new RangeError(`divRoundHalfUp: invalid operands ${numerator}/${denominator}`);
  }
  const r = numerator % denominator;
  const q = (numerator - r) / denominator;
  return r * 2 >= denominator ? q + 1 : q;
}

const sum = (xs: readonly number[]): number => xs.reduce((a, b) => a + b, 0);

/**
 * total을 weights 비례로 배분합니다. 라인별로 half-up 반올림하고, 잔액은 금액이 가장 큰 라인
 * (동률이면 앞 라인)에 넣습니다. 그 라인이 0 미만이나 자기 금액 초과가 되면 다음으로 큰 라인으로 넘깁니다.
 * 전제: 0 ≤ total ≤ sum(weights).
 */
export function allocateProportionally(total: number, weights: readonly number[]): number[] {
  const weightSum = sum(weights);
  if (!Number.isSafeInteger(total) || total < 0 || total > weightSum) {
    throw new RangeError(`allocateProportionally: total ${total} out of range 0..${weightSum}`);
  }
  if (total === 0) return weights.map(() => 0);

  const shares = weights.map((w) => divRoundHalfUp(total * w, weightSum));
  let remainder = total - sum(shares);
  const order = weights.map((_, i) => i).sort((a, b) => weights[b] - weights[a] || a - b);
  for (const i of order) {
    if (remainder === 0) break;
    const adj = remainder > 0 ? Math.min(remainder, weights[i] - shares[i]) : Math.max(remainder, -shares[i]);
    shares[i] += adj;
    remainder -= adj;
  }
  return shares;
}

const storeDateFormat = new Intl.DateTimeFormat('en-CA', {
  timeZone: STORE_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit',
});

/** 시각을 매장 현지(Asia/Seoul) 날짜 YYYY-MM-DD로 변환 */
export function toStoreDate(instant: Date): string {
  if (Number.isNaN(instant.getTime())) throw new RangeError('toStoreDate: invalid Date');
  const parts = storeDateFormat.formatToParts(instant);
  const get = (type: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === type)!.value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

function assertValidItem(item: LineItem): void {
  if (!Number.isSafeInteger(item.unitPrice) || item.unitPrice < 0) {
    throw new RangeError(`unitPrice must be a non-negative integer (sku=${item.sku})`);
  }
  if (!Number.isSafeInteger(item.qty) || item.qty < 0) {
    throw new RangeError(`qty must be a non-negative integer (sku=${item.sku})`);
  }
  if (!Object.prototype.hasOwnProperty.call(TAXABLE, item.category)) {
    throw new RangeError(`unknown category "${String(item.category)}" (sku=${item.sku})`);
  }
}

function evaluatePromo(
  base: readonly BaseLine[],
  rawCode: string | undefined,
  today: Date,
  table: readonly PromoDefinition[],
): PromoEvaluation {
  const zeros = base.map(() => 0);
  const code = rawCode?.trim().toUpperCase() ?? '';
  if (code === '') return { outcome: { status: 'none' }, perLine: zeros };

  const reject = (reason: PromoRejectReason): PromoEvaluation => ({
    outcome: { status: 'rejected', code, reason },
    perLine: zeros,
  });

  const def = table.find((p) => p.code.toUpperCase() === code);
  if (!def) return reject('unknown');
  if (toStoreDate(today) > def.validThrough) return reject('expired');

  const scope = def.categories as readonly Category[];
  const eligible = base.flatMap((b, i) =>
    DISCOUNTABLE[b.item.category] && scope.includes(b.item.category) && b.grossAmount > 0 ? [i] : [],
  );
  if (eligible.length === 0) return reject('no_eligible_items');

  const eligibleGross = sum(eligible.map((i) => base[i].grossAmount));
  if (eligibleGross < def.minEligibleAmount) return reject('below_minimum');

  const perLine = [...zeros];
  if (def.kind === 'percent') {
    for (const i of eligible) perLine[i] = divRoundHalfUp(base[i].afterMember * def.value, 100);
  } else {
    const weights = eligible.map((i) => base[i].afterMember);
    const amount = Math.min(def.value, sum(weights)); // 적용 대상 금액 초과 불가
    allocateProportionally(amount, weights).forEach((share, k) => { perLine[eligible[k]] = share; });
  }
  return { outcome: { status: 'applied', code: def.code, discount: sum(perLine) }, perLine };
}

/**
 * 장바구니 가격을 계산합니다. 유효하지 않은 코드는 throw하지 않고 promo.status='rejected'로 반환합니다.
 * today는 테스트와 재현을 위해 주입할 수 있습니다(기본값은 현재 시각).
 */
export function priceCart(
  cart: Cart,
  promoCode?: string,
  today: Date = new Date(),
  promoTable: readonly PromoDefinition[] = PROMO_CODES,
): PriceResult {
  if (!Object.prototype.hasOwnProperty.call(MEMBER_DISCOUNT_PERCENT, cart.memberTier)) {
    throw new RangeError(`unknown memberTier "${String(cart.memberTier)}"`);
  }
  cart.items.forEach(assertValidItem);
  const memberPercent = MEMBER_DISCOUNT_PERCENT[cart.memberTier];

  const base: BaseLine[] = cart.items.map((item) => {
    const grossAmount = item.unitPrice * item.qty;
    if (!Number.isSafeInteger(grossAmount)) throw new RangeError(`line amount overflow (sku=${item.sku})`);
    const memberDiscount = DISCOUNTABLE[item.category] ? divRoundHalfUp(grossAmount * memberPercent, 100) : 0;
    return { item, grossAmount, memberDiscount, afterMember: grossAmount - memberDiscount };
  });

  const { outcome, perLine } = evaluatePromo(base, promoCode, today, promoTable);

  const lines: PricedLine[] = base.map((b, i) => {
    const netAmount = b.afterMember - perLine[i];
    const taxable = TAXABLE[b.item.category];
    const vat = taxable ? divRoundHalfUp(netAmount, 11) : 0; // net × 10/110
    return {
      sku: b.item.sku, name: b.item.name, category: b.item.category,
      unitPrice: b.item.unitPrice, qty: b.item.qty,
      grossAmount: b.grossAmount, memberDiscount: b.memberDiscount, promoDiscount: perLine[i],
      netAmount, taxable, vat, supplyAmount: netAmount - vat,
    };
  });

  const total = sum(lines.map((l) => l.netAmount));
  return {
    lines,
    subtotal: sum(lines.map((l) => l.grossAmount)),
    memberDiscount: sum(lines.map((l) => l.memberDiscount)),
    promoDiscount: sum(lines.map((l) => l.promoDiscount)),
    total,
    vat: sum(lines.map((l) => l.vat)),
    taxableSupplyAmount: sum(lines.filter((l) => l.taxable).map((l) => l.supplyAmount)),
    exemptAmount: sum(lines.filter((l) => !l.taxable).map((l) => l.netAmount)),
    promo: outcome,
  };
}
```

## 2. `pricing.test.ts`

```ts
import { describe, expect, it } from 'vitest';
import {
  allocateProportionally, divRoundHalfUp, priceCart, toStoreDate,
  type Cart, type Category, type LineItem, type PriceResult, type PromoDefinition,
} from './pricing';

let seq = 0;
const item = (unitPrice: number, qty: number, category: Category, name = `item-${++seq}`): LineItem =>
  ({ sku: name, name, unitPrice, qty, category });
const cart = (items: LineItem[], memberTier: Cart['memberTier'] = 'none'): Cart => ({ items, memberTier });
const kst = (ymd: string, hms = '12:00:00') => new Date(`${ymd}T${hms}+09:00`);
const withoutPromo = ({ promo: _ignored, ...rest }: PriceResult) => rest;

function expectConsistent(r: PriceResult) {
  const s = (f: (l: PriceResult['lines'][number]) => number) => r.lines.reduce((a, l) => a + f(l), 0);
  expect(r.subtotal).toBe(s((l) => l.grossAmount));
  expect(r.memberDiscount).toBe(s((l) => l.memberDiscount));
  expect(r.promoDiscount).toBe(s((l) => l.promoDiscount));
  expect(r.total).toBe(s((l) => l.netAmount));
  expect(r.total).toBe(r.subtotal - r.memberDiscount - r.promoDiscount);
  expect(r.vat).toBe(s((l) => l.vat));
  expect(r.taxableSupplyAmount + r.vat + r.exemptAmount).toBe(r.total);
  for (const l of r.lines) {
    for (const v of [l.grossAmount, l.memberDiscount, l.promoDiscount, l.netAmount, l.vat, l.supplyAmount]) {
      expect(Number.isInteger(v)).toBe(true);
    }
    expect(l.netAmount).toBeGreaterThanOrEqual(0);
    if (l.category === 'alcohol') expect([l.memberDiscount, l.promoDiscount]).toEqual([0, 0]);
    if (!l.taxable) expect(l.vat).toBe(0);
  }
}

describe('반올림 헬퍼', () => {
  it('half-up 방식이며 은행가 반올림이 아니다', () => {
    expect(divRoundHalfUp(29_850, 100)).toBe(299); // 298.5 → 299
    expect(divRoundHalfUp(5, 2)).toBe(3);          // 2.5 → 3
    expect(divRoundHalfUp(29_849, 100)).toBe(298);
    expect(divRoundHalfUp(0, 7)).toBe(0);
  });
});

describe('기본 계산 / 부가세', () => {
  it('부가세는 포함가에서 분리하고 total에 더하지 않으며, grocery는 면세다', () => {
    const r = priceCart(cart([item(10_000, 1, 'grocery'), item(11_000, 1, 'household')]));
    expect(r).toMatchObject({ total: 21_000, vat: 1_000, exemptAmount: 10_000, taxableSupplyAmount: 10_000 });
    expect(r.lines[0]).toMatchObject({ taxable: false, vat: 0 });
    expect(r.promo).toEqual({ status: 'none' });
    expectConsistent(r);
  });

  it.each([[1, 0], [5, 0], [6, 1], [16, 1], [17, 2], [8_075, 734], [11_990, 1_090]])(
    '과세 결제액 %i원의 부가세는 %i원 (10/110, half-up)',
    (net, vat) => {
      const r = priceCart(cart([item(net, 1, 'household')]));
      expect(r.lines[0].vat).toBe(vat);
      expect(r.lines[0].supplyAmount).toBe(net - vat);
    },
  );

  it.each([[1990.5, 1], [-1, 1], [1000, 1.5], [1000, -2]])('잘못된 단가/수량(%s, %s)은 거부한다', (p, q) => {
    expect(() => priceCart(cart([item(p, q, 'grocery')]))).toThrow(RangeError);
  });
});

describe('Plus 멤버십', () => {
  it('5%를 라인별로 half-up 반올림한다', () => {
    const r = priceCart(cart([item(1_990, 3, 'grocery'), item(6_490, 1, 'grocery'), item(1_999, 1, 'household')], 'plus'));
    expect(r.lines.map((l) => l.memberDiscount)).toEqual([299, 325, 100]); // 298.5, 324.5, 99.95
    expectConsistent(r);
  });

  it('주류는 멤버십 할인을 받지 않는다', () => {
    const r = priceCart(cart([item(11_990, 1, 'alcohol')], 'plus'));
    expect(r.lines[0]).toMatchObject({ memberDiscount: 0, netAmount: 11_990, vat: 1_090 });
  });
});

describe('프로모션 코드: 인식과 거절 사유', () => {
  it.each(['fresh10', 'FRESH10', 'Fresh10', '  fresh10 '])('"%s"를 대소문자·공백과 무관하게 인식한다', (code) => {
    const r = priceCart(cart([item(40_000, 1, 'grocery')]), code, kst('2025-07-02'));
    expect(r.promo).toEqual({ status: 'applied', code: 'FRESH10', discount: 4_000 });
    expect(r.total).toBe(36_000);
  });

  it.each(['', '   '])('빈 코드 "%s"는 코드 없음으로 처리한다', (code) => {
    expect(priceCart(cart([item(40_000, 1, 'grocery')]), code, kst('2025-07-02')).promo).toEqual({ status: 'none' });
  });

  it('unknown: 결제를 막지 않고 프로모션 없는 가격을 반환한다', () => {
    const c = cart([item(30_000, 1, 'grocery'), item(5_500, 1, 'household')], 'plus');
    const r = priceCart(c, 'free100', kst('2025-06-01'));
    expect(r.promo).toEqual({ status: 'rejected', code: 'FREE100', reason: 'unknown' });
    expect(withoutPromo(r)).toEqual(withoutPromo(priceCart(c, undefined, kst('2025-06-01'))));
  });

  describe('expired: 유효기간은 Asia/Seoul 날짜 기준이며 해당일을 포함한다', () => {
    const c = cart([item(30_000, 1, 'grocery')]);
    it('2025-06-30 23:59:59.999 KST(UTC 14:59:59.999)까지 유효하다', () => {
      expect(priceCart(c, 'SAVE5000', new Date('2025-06-30T14:59:59.999Z')).promo.status).toBe('applied');
