## 1. `pricing.ts`

```ts
export type Category = 'grocery' | 'household' | 'alcohol';

export interface LineItem {
  sku: string;
  name: string;
  unitPrice: number;
  qty: number;
  category: Category;
}

export interface Cart {
  items: LineItem[];
  memberTier: 'none' | 'plus';
}

/** 문자열은 YYYY-MM-DD 형식의 Asia/Seoul 현지 날짜 */
export type Today = string | Date;

export type PromoCode = 'FRESH10' | 'SAVE5000' | 'HOME15';

export type PromoFailure =
  | 'unknown'
  | 'expired'
  | 'below_minimum'
  | 'no_eligible_items';

export type PromoResult =
  | { status: 'not_requested' }
  | { status: 'applied'; code: PromoCode }
  | { status: 'rejected'; code: string; reason: PromoFailure };

export interface PricedLine extends LineItem {
  subtotal: number;
  memberDiscount: number;
  promoDiscount: number;
  /** 할인 후 부가세 포함 결제 금액 */
  total: number;
  /** total에 이미 포함된 부가세 */
  tax: number;
}

export interface PricingResult {
  lines: PricedLine[];
  subtotal: number;
  memberDiscount: number;
  promoDiscount: number;
  tax: number;
  total: number;
  promo: PromoResult;
}

type Promotion = {
  eligibleCategories: readonly Category[];
  minimum: number;
  expiresOn: string;
} & (
  | { kind: 'percent'; percent: number }
  | { kind: 'fixed'; amount: number }
);

const PROMOTIONS = {
  FRESH10: {
    kind: 'percent',
    percent: 10,
    eligibleCategories: ['grocery', 'household'],
    minimum: 40_000,
    expiresOn: '2025-12-31',
  },
  SAVE5000: {
    kind: 'fixed',
    amount: 5_000,
    eligibleCategories: ['grocery', 'household'],
    minimum: 25_000,
    expiresOn: '2025-06-30',
  },
  HOME15: {
    kind: 'percent',
    percent: 15,
    eligibleCategories: ['household'],
    minimum: 0,
    expiresOn: '2025-12-31',
  },
} as const satisfies Record<PromoCode, Promotion>;

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function assertNonNegativeInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative safe integer`);
  }
}

function toAmount(value: bigint): number {
  if (value < 0n || value > MAX_SAFE) {
    throw new RangeError('Amount exceeds the supported integer range');
  }
  return Number(value);
}

function sum(values: readonly number[]): number {
  return toAmount(values.reduce((acc, value) => acc + BigInt(value), 0n));
}

/** 비음수 유리수를 정확하게 half-up 반올림한다. */
function roundFraction(numerator: bigint, denominator: bigint): number {
  return toAmount(
    (2n * numerator + denominator) / (2n * denominator),
  );
}

function percentage(amount: number, percent: number): number {
  return roundFraction(BigInt(amount) * BigInt(percent), 100n);
}

/**
 * 정액 할인 배분.
 * bases는 멤버십 할인 후 각 대상 라인의 금액이다.
 *
 * 비례액을 라인별 half-up 반올림한 뒤 큰 금액 순으로 잔액을 조정한다.
 * 동액이면 입력 순서가 우선이다.
 * 어느 라인도 음수 할인이나 라인 금액 초과 할인을 받지 않는다.
 */
export function allocateFixedDiscount(
  bases: readonly number[],
  requested: number,
): number[] {
  assertNonNegativeInteger(requested, 'requested');
  bases.forEach((base) => assertNonNegativeInteger(base, 'base'));

  const baseTotal = sum(bases);
  const target = Math.min(requested, baseTotal);

  if (target === 0) {
    return bases.map(() => 0);
  }

  const discounts = bases.map((base) =>
    roundFraction(
      BigInt(target) * BigInt(base),
      BigInt(baseTotal),
    ),
  );

  let residual = target - sum(discounts);

  const order = bases
    .map((base, index) => ({ base, index }))
    .sort((a, b) => b.base - a.base || a.index - b.index);

  for (const { base, index } of order) {
    if (residual === 0) break;

    const adjustment =
      residual > 0
        ? Math.min(residual, base - discounts[index])
        : -Math.min(-residual, discounts[index]);

    discounts[index] += adjustment;
    residual -= adjustment;
  }

  if (residual !== 0) {
    throw new Error('Internal allocation invariant violated');
  }

  return discounts;
}

function seoulDate(today: Today | undefined): string {
  if (today === undefined) {
    throw new TypeError('today is required when using a registered promo code');
  }

  if (typeof today === 'string') {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      throw new RangeError('today must be YYYY-MM-DD');
    }

    const parsed = new Date(`${today}T00:00:00.000Z`);
    if (
      !Number.isFinite(parsed.getTime()) ||
      parsed.toISOString().slice(0, 10) !== today
    ) {
      throw new RangeError('Invalid calendar date');
    }

    return today;
  }

  if (!(today instanceof Date) || !Number.isFinite(today.getTime())) {
    throw new RangeError('Invalid Date');
  }

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Seoul',
    calendar: 'gregory',
    numberingSystem: 'latn',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    era: 'short',
  }).formatToParts(today);

  const part = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((p) => p.type === type)!.value;

  const year = part('year');
  if (part('era') !== 'AD' || year.length > 4) {
    throw new RangeError('Unsupported calendar year');
  }

  return `${year.padStart(4, '0')}-${part('month')}-${part('day')}`;
}

function findPromotion(code: string): Promotion | undefined {
  return Object.hasOwn(PROMOTIONS, code)
    ? PROMOTIONS[code as PromoCode]
    : undefined;
}

export function priceCart(
  cart: Cart,
  promoCode?: string,
  today?: Today,
): PricingResult {
  if (cart.memberTier !== 'none' && cart.memberTier !== 'plus') {
    throw new TypeError('Invalid member tier');
  }
  if (promoCode !== undefined && typeof promoCode !== 'string') {
    throw new TypeError('promoCode must be one string');
  }

  // 새 객체만 생성하며 cart, items, today를 변경하지 않는다.
  const lines: PricedLine[] = cart.items.map((item) => {
    assertNonNegativeInteger(item.unitPrice, 'unitPrice');
    assertNonNegativeInteger(item.qty, 'qty');

    if (
      item.category !== 'grocery' &&
      item.category !== 'household' &&
      item.category !== 'alcohol'
    ) {
      throw new TypeError('Invalid category');
    }

    const subtotal = toAmount(BigInt(item.unitPrice) * BigInt(item.qty));
    const memberDiscount =
      cart.memberTier === 'plus' && item.category !== 'alcohol'
        ? percentage(subtotal, 5)
        : 0;

    return {
      ...item,
      subtotal,
      memberDiscount,
      promoDiscount: 0,
      total: subtotal - memberDiscount,
      tax: 0,
    };
  });

  // 총액도 안전한 정수 범위를 벗어나지 않도록 검사한다.
  const subtotal = sum(lines.map((line) => line.subtotal));
  const memberDiscount = sum(lines.map((line) => line.memberDiscount));

  const code = promoCode?.trim().toUpperCase() ?? '';
  let promo: PromoResult = { status: 'not_requested' };

  if (code !== '') {
    const definition = findPromotion(code);

    const reject = (reason: PromoFailure): PromoResult => ({
      status: 'rejected',
      code,
      reason,
    });

    if (!definition) {
      promo = reject('unknown');
    } else if (seoulDate(today) > definition.expiresOn) {
      promo = reject('expired');
    } else {
      const eligibleIndices = lines.flatMap((line, index) =>
        line.category !== 'alcohol' &&
        definition.eligibleCategories.includes(line.category) &&
        line.total > 0
          ? [index]
          : [],
      );

      const qualifyingAmount = sum(
        eligibleIndices.map((index) => lines[index].subtotal),
      );

      if (eligibleIndices.length === 0) {
        promo = reject('no_eligible_items');
      } else if (qualifyingAmount < definition.minimum) {
        promo = reject('below_minimum');
      } else {
        const bases = eligibleIndices.map((index) => lines[index].total);

        const discounts =
          definition.kind === 'fixed'
            ? allocateFixedDiscount(bases, definition.amount)
            : bases.map((base) => percentage(base, definition.percent));

        eligibleIndices.forEach((index, position) => {
          lines[index].promoDiscount = discounts[position];
          lines[index].total -= discounts[position];
        });

        promo = { status: 'applied', code: code as PromoCode };
      }
    }
  }

  for (const line of lines) {
    line.tax =
      line.category === 'grocery'
        ? 0
        : roundFraction(BigInt(line.total) * 10n, 110n);
  }

  return {
    lines,
    subtotal,
    memberDiscount,
    promoDiscount: sum(lines.map((line) => line.promoDiscount)),
    tax: sum(lines.map((line) => line.tax)),
    total: sum(lines.map((line) => line.total)),
    promo,
  };
}
